function table(headers,rows,empty='Tidak ada data yang sesuai dengan pencarian.'){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}"><div class="empty">${icon('search')}<strong>Belum ada hasil</strong>${empty}</div></td></tr>`}</tbody></table></div>`}
function pagination(total,size=7){return `<div class="table-bottom"><span>Menampilkan ${total?((pageIndex-1)*size+1):0}–${Math.min(pageIndex*size,total)} dari ${total} data</span><div class="pages"><button data-action="prev-page" aria-label="Halaman sebelumnya" ${pageIndex===1?'disabled':''}>‹</button>${Array.from({length:Math.max(1,Math.ceil(total/size))},(_,i)=>`<button class="${pageIndex===i+1?'current':''}" data-action="page:${i+1}" aria-label="Halaman ${i+1}">${i+1}</button>`).join('')}<button data-action="next-page:${Math.ceil(total/size)}" aria-label="Halaman berikutnya" ${pageIndex>=Math.ceil(total/size)?'disabled':''}>›</button></div></div>`}
