function formatDate(s){return s?s.split('-').reverse().join('/'):'—'}
function master(){const tabs=subnav([['obat','Obat & kemasan'],['pemasok','Pemasok'],['pasien','Pasien'],['dokter','Dokter & tanda tangan'],['kategori','Kategori & satuan']]);let rows=[],headers=[],data=[],action='new-drug';if(sub==='pemasok'){data=suppliers;headers=['KODE','NAMA PEMASOK','KONTAK PIC','TELEPON','TERMIN','STATUS',''];action='new-supplier';rows=data.filter(d=>JSON.stringify(d).toLowerCase().includes(search.toLowerCase())).map(d=>[d.id,`<strong>${esc(d.name)}</strong>`,esc(d.pic),esc(d.phone),`${d.term} hari`,badge('Aktif'),btn('Detail',`supplier:${d.id}`,'small')])}else if(sub==='pasien'){data=patients;headers=['NO. REKAM MEDIS','NAMA PASIEN','TANGGAL LAHIR','JENIS KELAMIN','TELEPON','ALERGI',''];action='new-patient';rows=data.filter(d=>JSON.stringify(d).toLowerCase().includes(search.toLowerCase())).map(d=>[d.id,`<strong>${esc(d.name)}</strong>`,formatDate(d.birth),d.sex,esc(d.phone),d.allergy&&d.allergy!=='Tidak diketahui'?badge(d.allergy,'red'):'—',btn('Rekam medis',`patient:${d.id}`,'small')])}else if(sub==='dokter'){data=doctors;headers=['KODE','NAMA DOKTER','SIP / STR','SPESIALISASI','TANDA TANGAN','STATUS',''];action='new-doctor';rows=data.filter(d=>JSON.stringify(d).toLowerCase().includes(search.toLowerCase())).map(d=>[d.id,`<strong>${esc(d.name)}</strong>`,esc(d.sip),esc(d.specialty),d.signature?badge('Terdaftar'):badge('Belum diunggah','amber'),badge('Aktif'),btn('Detail',`doctor:${d.id}`,'small')])}else if(sub==='kategori'){return heading('Kategori & satuan','Referensi klasifikasi dan satuan dasar obat.')+tabs+`<div class="dashboard-grid"><section class="card"><div class="card-head"><h2>Kategori obat</h2></div>${table(['KATEGORI','JUMLAH OBAT'],['Obat Bebas','Obat Bebas Terbatas','Obat Keras','Suplemen'].map(c=>[c,drugs.filter(d=>d.category===c).length]))}</section><section class="card"><div class="card-head"><h2>Satuan & konversi</h2></div>${table(['SATUAN DASAR','KEMASAN','KONVERSI'],[['Tablet','Box','100 tablet'],['Kapsul','Box','100 kapsul'],['Botol','Box','12 botol']])}<div class="state-panel"><div class="notice">Faktor konversi dicatat per obat. Transaksi final mempertahankan konversi historis.</div></div></section></div>`}else{data=drugs;headers=['NAMA OBAT','KATEGORI','HARGA JUAL','STOK','STATUS',''];rows=data.filter(d=>(d.name+' '+d.id+' '+d.generic).toLowerCase().includes(search.toLowerCase())&&(!filter||d.category===filter)).map(d=>[drugName(d),`${esc(d.category)}${d.rx?'<small>Wajib resep dokter</small>':''}`,money(d.price),`${num(d.stock)} <small>${esc(d.unit)}</small>`,statusDrug(d),btn('Detail',`drug:${d.id}`,'small')])}let total=rows.length;return heading({obat:'Master obat',pemasok:'Pemasok',pasien:'Data pasien',dokter:'Dokter & tanda tangan'}[sub]||'Master data','Kelola data utama untuk mendukung operasional apotek.',btn('Tambah '+({obat:'obat',pemasok:'pemasok',pasien:'pasien',dokter:'dokter'}[sub]||'obat'),action,'primary','plus'))+tabs+`<section class="card"><div class="toolbar">${searchBox()}${sub==='obat'?`<select id="filter" aria-label="Filter kategori"><option value="">Semua kategori</option>${['Obat Bebas','Obat Bebas Terbatas','Obat Keras','Suplemen'].map(c=>`<option ${filter===c?'selected':''}>${c}</option>`).join('')}</select>`:''}<span style="margin-left:auto;font-size:10px;color:var(--muted)">${total} data terdaftar</span>${btn('Ekspor CSV','export','','download')}</div>${table(headers,rows.slice((pageIndex-1)*7,pageIndex*7))}${pagination(total)}</section>`}
function purchases(){return heading('Pembelian','Kelola pemesanan dan penerimaan barang dari pemasok.',btn('Buat purchase order','new-po','primary','plus'))+subnav([['po','Purchase order'],['penerimaan','Penerimaan barang'],['riwayat','Riwayat pembelian']])+`<div class="module-stats"><div class="mini-stat">PO menunggu penerimaan<strong>${orders.filter(o=>['Dipesan','Parsial'].includes(o.status)).length}</strong></div><div class="mini-stat">Penerimaan selesai<strong>${orders.filter(o=>o.status==='Diterima').length}</strong></div><div class="mini-stat">Nilai pembelian contoh<strong>${money(orders.reduce((s,o)=>s+o.total,0))}</strong></div></div><section class="card"><div class="toolbar">${searchBox('Cari nomor PO atau pemasok…')}${sub==='penerimaan'?btn('Terima barang','receive','primary','box'):''}</div>${table(['NOMOR PO','PEMASOK','TANGGAL','ITEM','TOTAL','STATUS',''],orders.filter(o=>JSON.stringify(o).toLowerCase().includes(search.toLowerCase())&&(sub!=='penerimaan'||['Dipesan','Parsial'].includes(o.status))&&(sub!=='riwayat'||o.status==='Diterima')).map(o=>[`<strong>${o.id}</strong>`,esc(o.supplier),o.date,`${o.items} item`,money(o.total),badge(o.status),btn('Detail',`po:${o.id}`,'small')]))}</section>`}
function inventory(){let content='';if(sub==='opname'){content=`<section class="card"><div class="card-head"><div><h2>Sesi stok opname</h2><p>Snapshot → hitung fisik → persetujuan → posting</p></div>${btn('Mulai opname','new-opname','primary','plus')}</div>${state.opname?table(['NOMOR OPNAME','PETUGAS','RUANG LINGKUP','STATUS',''],[[state.opname.id,'Rofi Firdaus',state.opname.scope,badge(state.opname.status),btn('Lanjutkan','review-opname','small')]]):'<div class="empty">'+icon('stock')+'<strong>Belum ada sesi opname</strong>Mulai sesi untuk mengambil snapshot stok sistem.</div>'}</section>`}else if(sub==='kartu'){content=`<section class="card"><div class="toolbar">${searchBox('Cari obat atau referensi transaksi…')}</div>${table(['WAKTU','OBAT','SUMBER MUTASI','REFERENSI','MASUK','KELUAR','PETUGAS'],ledger.filter(l=>JSON.stringify(l).toLowerCase().includes(search.toLowerCase())).map(l=>[l.time,esc(l.drug),badge(l.type,'blue'),`<button class="btn text" data-action="ledger:${l.ref}">${esc(l.ref)}</button>`,`<span class="positive">+${l.in}</span>`,l.out,esc(l.user)]))}</section>`}else{let data=drugs.filter(d=>(d.name+' '+d.batch).toLowerCase().includes(search.toLowerCase())&&(sub!=='expired'||expired(d)||nearExpiry(d))&&(!filter||filter==='minimum'&&d.stock<d.min||filter==='expired'&&expired(d)||filter==='available'&&available(d)));content=`<section class="card"><div class="toolbar">${searchBox('Cari obat atau nomor batch…')}<select id="filter" aria-label="Filter status stok"><option value="">Semua status</option><option value="minimum" ${filter==='minimum'?'selected':''}>Stok minimum</option><option value="expired" ${filter==='expired'?'selected':''}>Kedaluwarsa</option><option value="available" ${filter==='available'?'selected':''}>Layak jual</option></select>${btn('Ekspor CSV','export','','download')}</div>${table(['OBAT','NOMOR BATCH','KEDALUWARSA','SALDO','LOKASI','STATUS',''],data.slice((pageIndex-1)*7,pageIndex*7).map(d=>[drugName(d),esc(d.batch),formatDate(d.expiry),`${d.stock} ${d.unit.toLowerCase()}`,'Rak A-01',statusDrug(d),btn('Kartu stok',`stock:${d.id}`,'small')]))}${pagination(data.length)}</section>`}return heading('Persediaan','Pantau saldo per batch, masa berlaku, dan pergerakan stok.',btn('Stok opname','new-opname','primary','stock'))+subnav([['batch','Stok per batch'],['kartu','Kartu stok'],['opname','Stok opname'],['expired','Alert kedaluwarsa']])+`<div class="module-stats"><div class="mini-stat">Obat terdaftar<strong>${drugs.length} <small>SKU</small></strong></div><div class="mini-stat">Di bawah minimum<strong>${drugs.filter(d=>d.stock<d.min&&!expired(d)).length}</strong></div><div class="mini-stat">Mendekati kedaluwarsa<strong>${drugs.filter(nearExpiry).length}</strong></div><div class="mini-stat">Batch kedaluwarsa<strong class="text-red">${drugs.filter(expired).length}</strong></div></div>`+content}
function services(){let rows=patients.filter(p=>JSON.stringify(p).toLowerCase().includes(search.toLowerCase()));return heading('Layanan pasien','Dari pendaftaran dan pemeriksaan hingga resep dokter.',btn('Daftarkan kunjungan','new-visit','primary','plus'))+subnav([['kunjungan','Kunjungan hari ini'],['medis','Rekam medis'],['resep','Resep dokter']])+`<section class="card"><div class="toolbar">${searchBox('Cari pasien atau nomor rekam medis…')}${sub==='resep'?btn('Buat resep','new-rx','primary','plus'):''}</div>${sub==='resep'?table(['NOMOR RESEP','PASIEN','DOKTER','WAKTU','STATUS',''],prescriptions.filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase())).map(r=>[r.id,esc(r.patient),esc(r.doctor),r.time+' WIB',badge(r.status),btn('Lihat resep',`rx:${r.id}`,'small')])):table(['ANTREAN','PASIEN','NO. REKAM MEDIS','KELUHAN','DOKTER','STATUS',''],rows.map((p,i)=>[`<span class="badge gray">A-${String(i+1).padStart(3,'0')}</span>`,`<strong>${esc(p.name)}</strong>${p.allergy&&p.allergy!=='Tidak diketahui'?`<small class="text-red">⚠ Alergi ${esc(p.allergy)}</small>`:''}`,p.id,esc(p.complaint),esc(p.doctor),badge(p.status),btn(sub==='medis'?'Rekam medis':'Periksa',`${sub==='medis'?'patient':'examine'}:${p.id}`,'small')]))}</section>`}
function pharmacy(){return heading('Antrean farmasi','Verifikasi resep, siapkan obat, dan catat penyerahan.',dateFilter())+`<div class="module-stats">${['Menunggu','Disiapkan','Diserahkan'].map(s=>`<div class="mini-stat">${s}<strong>${prescriptions.filter(r=>r.status===s).length} <small>resep</small></strong></div>`).join('')}</div><section class="card"><div class="toolbar">${searchBox('Cari resep, pasien, atau dokter…')}<select id="filter" aria-label="Status resep"><option value="">Semua status</option>${['Menunggu','Disiapkan','Diserahkan'].map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select></div>${table(['NOMOR RESEP','PASIEN','DOKTER','ALERGI','WAKTU','STATUS',''],prescriptions.filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase())&&(!filter||r.status===filter)).map(r=>[r.id,`<strong>${esc(r.patient)}</strong>`,esc(r.doctor),r.allergy!=='Tidak diketahui'?badge(r.allergy,'red'):'—',r.time+' WIB',badge(r.status),btn(r.status==='Menunggu'?'Verifikasi':r.status==='Disiapkan'?'Penyerahan':'Detail',`rx:${r.id}`,'small')]))}</section>`}
function subtotal(){return cart.reduce((sum,c)=>sum+drugs.find(d=>d.id===c.id).price*c.qty,0)}
function pos(){const total=subtotal();return heading('Kasir / POS','Penjualan cepat, pembayaran manual, dan alokasi batch FEFO.',`${btn('Riwayat transaksi','history','','clock')}${btn('Retur penjualan','return','','arrow')}`)+`<div class="pos-layout"><section class="card"><div class="toolbar">${searchBox('Cari nama obat, SKU, atau barcode…','pos-search')}<select id="pos-category" aria-label="Kategori obat"><option value="">Semua kategori</option>${['Obat Bebas','Obat Bebas Terbatas','Obat Keras','Suplemen'].map(c=>`<option ${filter===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="product-grid">${drugs.filter(d=>(d.name+' '+d.id+' '+(d.barcode||'')).toLowerCase().includes(search.toLowerCase())&&(!filter||d.category===filter)&&!expired(d)&&d.active).map(d=>`<button class="product" data-action="add-cart:${d.id}" ${d.stock<=0?'disabled':''}><span class="product-visual">${icon('pill')}</span><strong>${esc(d.name)}</strong><small>${esc(d.category)} · Stok ${d.stock}</small><b>${money(d.price)}</b><small>/ ${esc(d.unit.toLowerCase())}${d.rx?' · Wajib resep':''}</small></button>`).join('')||'<div class="empty"><strong>Obat tidak ditemukan</strong>Ubah kata pencarian atau kategori.</div>'}</div><div class="notice" style="margin:0 20px 20px">${icon('check')} Batch kedaluwarsa diblokir. Stok dipotong setelah pembayaran final.</div></section><aside class="card"><div class="card-head"><div><h2>Keranjang penjualan</h2><p>TRX-20261028-${String(49+transactions.length-3).padStart(3,'0')} · Draft</p></div>${btn('Kosongkan','clear-cart','text')}</div><div class="cart-info"><select id="pos-type" aria-label="Jenis transaksi"><option ${posType==='Umum'?'selected':''}>Umum</option><option ${posType==='Resep'?'selected':''}>Resep</option></select>${posType==='Resep'?`<select id="pos-rx" aria-label="Referensi resep" required><option value="">Pilih referensi resep</option>${prescriptions.map(r=>`<option value="${r.id}" ${selectedRx===r.id?'selected':''}>${r.id} · ${esc(r.patient)}</option>`).join('')}</select>`:''}<span style="font-size:10px;color:var(--muted)">${posType==='Resep'&&selectedRx?esc(prescriptions.find(r=>r.id===selectedRx)?.patient):'Pelanggan umum'} · Kasir: Rofi Firdaus</span></div><div>${cart.length?cart.map(c=>{const d=drugs.find(d=>d.id===c.id);return `<div class="cart-line"><div class="cart-name"><strong>${esc(d.name)}</strong><small>${money(d.price)} · ${d.batch}</small><small>FEFO · ED ${formatDate(d.expiry)}</small></div><div class="qty"><button data-action="qty:${d.id}:-1" aria-label="Kurangi ${esc(d.name)}">−</button>${c.qty}<button data-action="qty:${d.id}:1" aria-label="Tambah ${esc(d.name)}">+</button></div></div>`}).join(''):`<div class="empty">${icon('cart')}<strong>Keranjang masih kosong</strong>Pilih obat untuk memulai penjualan.</div>`}</div><div class="totals"><div class="total-line"><span>Subtotal (${cart.reduce((n,c)=>n+c.qty,0)} item)</span><span>${money(total)}</span></div><div class="total-line"><span>Diskon / pajak</span><span>Rp0 / Rp0</span></div><div class="total-line grand"><span>Total pembayaran</span><span>${money(total)}</span></div><label class="field"><span>Metode pembayaran *</span><select id="payment"><option ${payment==='Tunai'?'selected':''}>Tunai</option><option ${payment==='Transfer'?'selected':''}>Transfer</option><option ${payment==='QRIS manual'?'selected':''}>QRIS manual</option></select></label>${payment==='Tunai'?`<label class="field"><span>Nominal diterima (Rp) *</span><input id="paid" type="number" min="0" value="${paid||''}" placeholder="0"><small id="paid-error"></small></label><div class="total-line"><span>Kembalian</span><strong id="change">${money(Math.max(0,paid-total))}</strong></div>`:`<label class="field"><span>Referensi pembayaran</span><input id="payment-reference" placeholder="Nomor transfer / referensi manual"></label>`}<button class="btn primary" data-action="checkout" ${!cart.length?'disabled':''}>${icon('check')}Selesaikan pembayaran <span style="opacity:.6">F8</span></button><div class="pos-foot">F2 Cari obat · F8 Pembayaran · Tanpa payment gateway</div></div></aside></div>`}
function reports(){let total=transactions.reduce((s,t)=>s+(t.status==='Lunas'?t.total:0),0);return heading('Laporan operasional','Telusuri penjualan, pembelian, persediaan, dan layanan apotek.',btn('Ekspor CSV','export','primary','download'))+`<section class="card"><form class="toolbar" id="report-filter"><label class="field"><span>Jenis laporan</span><select id="report-type"><option>Penjualan</option><option>Pembelian</option><option>Persediaan</option><option>Kedaluwarsa</option><option>Mutasi stok</option><option>Resep</option></select></label><label class="field"><span>Dari tanggal *</span><input type="date" id="report-from" value="2026-10-28" required></label><label class="field"><span>Sampai tanggal *</span><input type="date" id="report-to" value="2026-10-28" required></label><button class="btn primary" style="align-self:end">Tampilkan laporan</button></form><div class="state-panel" id="report-content"><div class="report-summary"><div><span style="font-size:11px">Penjualan · 28/10/2026</span><p>Transaksi final setelah retur (data contoh)</p></div><strong>${money(total)}</strong></div>${transactionTable()}</div></section>`}
function transactionTable(){return table(['NOMOR TRANSAKSI','WAKTU','PELANGGAN','TOTAL','METODE','STATUS',''],transactions.map(t=>[t.id,t.time+' WIB',esc(t.customer),money(t.total),esc(t.method),badge(t.status),btn('Detail',`trx:${t.id}`,'small')]))}
function settings(){return heading('Pengaturan','Kelola profil apotek, operasional, dan akses pengguna.')+`<div class="settings-grid"><div class="settings-menu">${[['profil','Profil apotek'],['operasional','Operasional'],['pengguna','Pengguna & hak akses'],['audit','Audit log'],['states','Komponen & state UI']].map(([key,label])=>`<button class="${sub===key?'active':''}" data-action="sub:${key}">${label}</button>`).join('')}</div><section class="card">${sub==='audit'?`<div class="card-head"><h2>Jejak audit simulasi</h2></div>${audits.map(a=>`<div class="audit"><strong>${esc(a.action)}</strong> · ${esc(a.object)}<p>${a.time} · Rofi Firdaus · Data sensitif disamarkan</p></div>`).join('')}`:sub==='pengguna'?`<div class="card-head"><div><h2>Pengguna & hak akses</h2><p>Matriks akses untuk rancangan pengembangan</p></div></div>${table(['PERAN','AKSES UTAMA'],[['Admin','Seluruh modul dan konfigurasi'],['Owner / Manager','Monitoring, laporan, persetujuan stok'],['Gudang / Pembelian','Obat, pemasok, PO, penerimaan, stok'],['Dokter','Pasien, pemeriksaan, resep dan tanda tangan sendiri'],['Apoteker / Asisten','Verifikasi, penyiapan, penyerahan resep'],['Kasir','POS, pembayaran, struk, retur berizin']])}<div class="state-panel"><div class="notice amber">Prototipe menggunakan profil Admin. Pembatasan akses dan autentikasi perlu diterapkan di backend.</div></div>`:sub==='states'?states():`<form id="settings-form" class="settings-body"><h2 class="section-title">${sub==='operasional'?'Konfigurasi operasional':'Identitas apotek'}</h2><div class="form-grid">${sub==='operasional'?field('Format nomor dokumen','format','TRX-{YYYY}{MM}{DD}-{SEQ}','text',true)+field('Batas alert kedaluwarsa (hari)','expired',state.settings.expired,'number',true)+selectField('Metode stok keluar','fefo',['FEFO'],'FEFO')+selectField('Printer struk','printer',['Browser print'],'Browser print'):`${field('Nama apotek','name',state.settings.name,'text',true)}${field('Nomor izin apotek','license',state.settings.license)}${field('Alamat','address',state.settings.address,'text',true,'full')}${field('Telepon','phone',state.settings.phone,'tel',true)}`}<div class="field full"><div class="notice">Perubahan pada prototipe hanya berlaku selama sesi browser ini.</div></div></div><div class="actions" style="justify-content:flex-end;margin-top:20px"><button class="btn primary">Simpan pengaturan</button></div></form>`}</section></div>`}
function states(){return `<div class="state-panel"><h2 class="section-title">Design system & state komponen</h2><div class="actions" style="flex-wrap:wrap;margin-bottom:20px">${['Draft','Menunggu','Disiapkan','Selesai','Dibatalkan'].map(s=>badge(s)).join('')}</div><div class="form-grid"><div><h3 class="section-title">Loading</h3><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div><div><h3 class="section-title">Belum ada data</h3><div class="empty" style="padding:20px"><strong>Belum ada transaksi</strong>Transaksi baru akan tampil di sini.</div></div></div><div class="notice red">Gagal memuat data. Periksa koneksi Anda. ${btn('Coba lagi','retry','small')}</div><div class="notice amber">Akses terbatas. Peran Anda tidak memiliki izin untuk melihat data klinis.</div><label class="field"><span>Nama obat *</span><input value="" aria-invalid="true" style="border-color:#cc7f6d" placeholder="Masukkan nama obat"><small class="text-red">Nama obat wajib diisi.</small></label><h3 class="section-title">Token desain</h3><p style="font-size:11px;line-height:2;color:var(--muted)">Primary #18765B · Background #F6F8F6 · Text #243B33<br>Manrope untuk judul · DM Sans untuk teks · Spacing 8 pt<br>Radius 7–12 px · Fokus keyboard terlihat · Status disertai teks</p></div>`}
function field(label,name,value='',type='text',required=false,cls=''){return `<label class="field ${cls}"><span>${label}${required?' *':''}</span><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="any"':''} ${type==='date'&&name==='birth'?'max="2026-10-28"':''}></label>`}
function textField(label,name,value='',required=false){return `<label class="field full"><span>${label}${required?' *':''}</span><textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea></label>`}
function selectField(label,name,options,value='',required=true){return `<label class="field"><span>${label}${required?' *':''}</span><select name="${name}" ${required?'required':''}>${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`}
function modal(title,desc,body,foot='',wide=false){lastFocus=document.activeElement;modalDirty=false;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${desc}</p></div><button class="icon-btn" data-action="close-modal" aria-label="Tutup dialog">×</button></div><div class="modal-body">${body}</div><div class="modal-foot">${foot||btn('Tutup','close-modal')}</div></section></div>`;document.body.style.overflow='hidden';$('.modal input, .modal select, .modal button')?.focus()}
function closeModal(force=false){if(!force&&modalDirty&&!confirm('Tutup formulir? Perubahan yang belum disimpan akan hilang.'))return;$('#modal-root').innerHTML='';document.body.style.overflow='';lastFocus?.focus();modalDirty=false}
function formModal(title,desc,id,body,save='Simpan',wide=false){modal(title,desc,`<form id="${id}">${body}<button type="submit" hidden></button></form>`,`${btn('Batal','close-modal')}<button class="btn primary" type="submit" form="${id}">${icon('check')}${save}</button>`,wide)}
function drugForm(id){const d=drugs.find(d=>d.id===id)||{id:`OBT-${String(drugs.length+1).padStart(3,'0')}`,active:true,conversion:100,min:0,price:0};formModal(id?'Detail & ubah obat':'Tambah obat','Identitas, harga & satuan, serta pengendalian stok. * Wajib diisi.','drug-form',`<input type="hidden" name="originalId" value="${id||''}"><h3 class="section-title">Identitas obat</h3><div class="form-grid">${field('Kode obat / SKU','id',d.id,'text',true)}${field('Barcode','barcode',d.barcode)}${field('Nama obat','name',d.name,'text',true,'full')}${field('Nama generik','generic',d.generic)}${selectField('Kategori','category',['Obat Bebas','Obat Bebas Terbatas','Obat Keras','Suplemen'],d.category)}${selectField('Bentuk / sediaan','form',['Tablet','Kapsul','Sirup','Salep','Larutan'],d.form,false)}${field('Kekuatan / dosis','strength',d.strength)}</div><h3 class="section-title">Harga & satuan</h3><div class="form-grid">${selectField('Satuan dasar','unit',['Tablet','Kapsul','Botol','Tube'],d.unit)}${selectField('Satuan pembelian','buyUnit',['Box','Strip','Botol'],d.buyUnit)}${field('Isi per satuan pembelian','conversion',d.conversion,'number',true)}${field('Harga beli default (Rp)','buyPrice',d.buyPrice,'number')}${field('Harga jual dasar (Rp)','price',d.price,'number',true)}</div><h3 class="section-title">Pengendalian stok</h3><div class="form-grid">${field('Stok minimum','min',d.min,'number',true)}${field('Stok maksimum','max',d.max,'number')}<label class="check-row"><input type="checkbox" name="active" ${d.active?'checked':''}> Status aktif</label><label class="check-row"><input type="checkbox" name="rx" ${d.rx?'checked':''}> Memerlukan resep dokter</label></div><p style="font-size:10px;color:var(--muted)">Saldo stok dikelola melalui penerimaan, penjualan, dan opname.</p>`)}
function personForm(type,id){const isPatient=type==='patient',isDoctor=type==='doctor';const data=isPatient?patients:isDoctor?doctors:suppliers;const d=data.find(d=>d.id===id)||{};const title=isPatient?'pasien':isDoctor?'dokter':'pemasok';let body=field('Nama lengkap'+(type==='supplier'?' pemasok':''),'name',d.name,'text',true);if(isPatient)body+=field('NIK (opsional, 16 digit)','nik','','text')+field('Tanggal lahir','birth',d.birth,'date',true)+selectField('Jenis kelamin','sex',['Perempuan','Laki-laki'],d.sex)+field('Telepon','phone',d.phone,'tel')+textField('Alamat','address',d.address)+textField('Alergi obat','allergy',d.allergy)+field('Kontak darurat','emergency',d.emergency)+textField('Catatan','note',d.note);else if(isDoctor)body+=field('Nomor SIP / STR','sip',d.sip)+field('Spesialisasi','specialty',d.specialty)+`<label class="field"><span>Tanda tangan PNG / JPG (maks. 2 MB)</span><input type="file" name="signature" accept="image/png,image/jpeg"><small>Gambar tanda tangan untuk resep.</small></label>${d.signature?`<div class="field"><span>Pratinjau tanda tangan</span><img src="${d.signature}" alt="Tanda tangan dokter" style="max-width:160px;max-height:80px;object-fit:contain"></div>`:''}`+field('Tanggal mulai berlaku','effective','','date')+`<label class="check-row"><input type="checkbox" name="active" checked> Dokter aktif</label>`;else body+=field('Kontak PIC','pic',d.pic)+field('Telepon','phone',d.phone,'tel')+field('Email','email',d.email,'email')+field('NPWP','npwp',d.npwp)+field('Termin bayar (hari)','term',d.term||0,'number')+textField('Alamat','address',d.address);formModal((id?'Ubah ':'Tambah ')+title,'Nomor identitas dibuat otomatis. * Wajib diisi.',`person-form`,`<input type="hidden" name="type" value="${type}"><input type="hidden" name="originalId" value="${id||''}"><div class="form-grid">${body}</div>`)}
function visitForm(){formModal('Daftarkan kunjungan','Kunjungan baru · 28/10/2026 · Antrean otomatis','visit-form',`<div class="form-grid">${selectField('Pasien','patient',patients.map(p=>`${p.id} · ${p.name}`))}${selectField('Dokter pemeriksa','doctor',doctors.filter(d=>d.active).map(d=>d.name))}${selectField('Jenis kunjungan','type',['Baru','Kontrol'])}${field('Tanggal kunjungan','date','2026-10-28','date',true)}${textField('Keluhan utama','complaint','',true)}</div><div style="margin-top:15px">${btn('+ Tambah pasien baru','new-patient','text')}</div>`,'Daftarkan kunjungan')}
function patientDetail(id){const p=patients.find(p=>p.id===id);modal('Rekam medis pasien',`${p.id} · Data klinis terbatas`,`${p.allergy&&p.allergy!=='Tidak diketahui'?`<div class="notice red">⚠ Alergi obat: <strong>${esc(p.allergy)}</strong></div>`:''}<dl class="detail-grid"><div><dt>Nama pasien</dt><dd>${esc(p.name)}</dd></div><div><dt>Tanggal lahir</dt><dd>${formatDate(p.birth)}</dd></div><div><dt>Jenis kelamin</dt><dd>${p.sex}</dd></div><div><dt>Telepon</dt><dd>${esc(p.phone)}</dd></div><div><dt>Dokter</dt><dd>${esc(p.doctor)}</dd></div><div><dt>Status kunjungan</dt><dd>${badge(p.status)}</dd></div></dl><h3 class="section-title">Timeline kunjungan</h3><div class="timeline"><div><strong>28 Oktober 2026 · Kunjungan hari ini</strong><p>Keluhan: ${esc(p.complaint)}<br>${p.exam?`Diagnosis: ${esc(p.exam.diagnosis)}<br>Rencana: ${esc(p.exam.plan)}<br>Catatan final · koreksi memerlukan amendemen`:'Menunggu catatan pemeriksaan dokter.'}</p></div></div>`,`${btn('Ubah identitas',`edit-patient:${p.id}`)}${btn(p.exam?'Lihat catatan final':'Mulai pemeriksaan',`examine:${p.id}`,'primary')}`)}
function examine(id){const p=patients.find(p=>p.id===id);if(p.exam){modal('Catatan pemeriksaan final',`${p.id} · ${esc(p.name)}`,`<div class="notice">Catatan final terkunci. Koreksi harus dicatat sebagai amendemen dengan alasan.</div><dl class="detail-grid"><div><dt>Subjektif</dt><dd>${esc(p.exam.subjective)}</dd></div><div><dt>Diagnosis</dt><dd>${esc(p.exam.diagnosis)}</dd></div><div><dt>Rencana</dt><dd>${esc(p.exam.plan)}</dd></div></dl>${p.amendment?`<h3 class="section-title">Amendemen</h3><p>${esc(p.amendment.text)}</p><p>Alasan: ${esc(p.amendment.reason)}</p><small>Rofi Firdaus · 28/10/2026 · sesi demo</small>`:''}`,`${btn('Tutup','close-modal')}${btn('Tambah amendemen',`amend:${id}`)}${btn('Buat resep',`new-rx:${id}`,'primary')}`);return}formModal('Pemeriksaan pasien',`${esc(p.name)} · ${p.id} · ${esc(p.doctor)}`,'exam-form',`<input type="hidden" name="patientId" value="${p.id}">${p.allergy&&p.allergy!=='Tidak diketahui'?`<div class="notice red">Alergi obat: ${esc(p.allergy)}</div>`:''}<h3 class="section-title">S — Subjektif</h3><div class="form-grid">${textField('Anamnesis / keluhan','subjective',p.complaint,true)}</div><h3 class="section-title">O — Objektif</h3><div class="form-grid">${field('Tekanan darah (mmHg)','blood','120/80')}${field('Nadi (x/menit)','pulse',80,'number')}${field('Suhu tubuh (°C)','temperature',36.5,'number')}${field('Berat badan (kg)','weight','','number')}${field('Tinggi badan (cm)','height','','number')}${textField('Temuan objektif','objective')}</div><h3 class="section-title">A / P — Assessment & rencana</h3><div class="form-grid">${textField('Diagnosis / assessment','diagnosis','',true)}${textField('Rencana / tindakan','plan','',true)}${textField('Catatan tindak lanjut','followup')}</div><div class="notice amber" style="margin-top:18px">Finalisasi akan mengunci catatan pemeriksaan. Perubahan berikutnya dicatat sebagai amendemen.</div>`,'Finalkan pemeriksaan')}
function rxForm(patientId){const p=patients.find(p=>p.id===patientId)||patients[0];formModal('Buat resep dokter','Resep terhubung ke pasien, kunjungan, dan dokter pemeriksa.','rx-form',`<div class="form-grid">${selectField('Pasien / kunjungan','patient',patients.map(p=>`${p.id} · ${p.name}`),`${p.id} · ${p.name}`)}${selectField('Dokter','doctor',doctors.map(d=>d.name),p.doctor)}</div><div class="notice amber" style="margin-top:18px" id="rx-allergy">Alergi pasien: ${esc(p.allergy||'Tidak diketahui')}. Verifikasi sebelum meresepkan.</div><div class="form-grid">${selectField('Obat','drug',drugs.filter(d=>d.active&&!expired(d)).map(d=>`${d.id} · ${d.name}`))}${field('Jumlah diresepkan','qty',10,'number',true)}${field('Dosis per konsumsi','dose','1 tablet','text',true)}${field('Frekuensi','frequency','3× sehari','text',true)}${selectField('Rute pemberian','route',['Oral','Topikal','Lainnya'])}${field('Durasi','duration','3 hari')}${textField('Aturan pakai','instruction','Sesudah makan',true)}${textField('Catatan dokter','note')}</div><div class="notice" style="margin-top:18px">Tanda tangan diambil dari profil dokter. Resep final menyimpan snapshot gambar dan aturan pakai.</div>`,'Finalkan & kirim ke farmasi')}
function rxDetail(id){const r=prescriptions.find(r=>r.id===id),d=drugs.find(d=>d.id===r.drug);modal('Detail resep',`${r.id} · ${r.time} WIB`,`${r.allergy!=='Tidak diketahui'?`<div class="notice red">⚠ Alergi pasien: ${esc(r.allergy)}. Pastikan kesesuaian obat.</div>`:''}<dl class="detail-grid"><div><dt>Kunjungan / rekam medis</dt><dd>${esc(r.visitId||'?')}<small>${esc(r.patientId||'?')}</small></dd></div><div><dt>Pasien</dt><dd>${esc(r.patient)}</dd></div><div><dt>Dokter</dt><dd>${esc(r.doctor)}</dd></div><div><dt>Status</dt><dd>${badge(r.status)}</dd></div></dl>${table(['OBAT','DOSIS','FREKUENSI','QTY','ATURAN PAKAI'],[[esc(d.name),esc(r.dose),esc(r.frequency),`${r.qty} ${d.unit.toLowerCase()}`,esc(r.instruction)]])}<h3 class="section-title">Alokasi batch FEFO</h3><div class="notice ${available(d)&&d.stock>=r.qty?'':'red'}">Batch ${esc(d.batch)} · ED ${formatDate(d.expiry)} · Stok ${d.stock} ${d.unit.toLowerCase()}<br>${available(d)&&d.stock>=r.qty?'Batch layak digunakan.':'Batch tidak layak atau stok tidak cukup. Penyerahan diblokir.'}</div>${r.status==='Disiapkan'?`<label class="field"><span>Penerima obat (opsional)</span><input id="recipient" placeholder="Nama penerima"></label>`:''}<p style="font-size:10px;color:var(--muted)">Stok dipotong satu kali saat penyerahan. Pembayaran resep tidak memotong stok kembali.</p>`,`${btn('Cetak resep',`print-rx:${id}`,'','print')}${r.status==='Menunggu'?btn('Verifikasi & siapkan',`prepare:${id}`,'primary'):r.status==='Disiapkan'?btn('Konfirmasi penyerahan',`dispense:${id}`,'primary'):btn('Buka kasir',`pay-rx:${id}`,'primary')}`,true)}
function poForm(){formModal('Buat purchase order','PO draft tidak mengubah persediaan. * Wajib diisi.','po-form',`<div class="form-grid">${field('Tanggal PO','date','2026-10-28','date',true)}${selectField('Pemasok','supplier',suppliers.map(s=>s.name))}${field('Estimasi tiba','eta','','date')}${selectField('Termin pembayaran','term',['Tunai','Kredit'])}${textField('Catatan','note')}</div><h3 class="section-title">Item pemesanan</h3><div class="form-grid">${selectField('Obat','drug',drugs.map(d=>`${d.id} · ${d.name}`))}${selectField('Kemasan','unit',['Box','Strip'])}${field('Qty dipesan','qty',1,'number',true)}${field('Harga satuan (Rp)','price',100000,'number',true)}${field('Diskon item (Rp)','discount',0,'number')}${field('Pajak (Rp)','tax',0,'number')}</div><div class="notice" style="margin-top:20px">Total PO: <strong id="po-total">Rp100.000</strong></div>`,'Simpan draft')}
function poDetail(id){const o=orders.find(o=>o.id===id);modal('Detail purchase order',o.id,`<dl class="detail-grid"><div><dt>Pemasok</dt><dd>${esc(o.supplier)}</dd></div><div><dt>Tanggal</dt><dd>${o.date}</dd></div><div><dt>Status</dt><dd>${badge(o.status)}</dd></div><div><dt>Nilai PO</dt><dd>${money(o.total)}</dd></div><div><dt>Jumlah item</dt><dd>${o.items}</dd></div><div><dt>Petugas</dt><dd>Rofi Firdaus</dd></div></dl>${o.drug?table(['OBAT','QTY','KEMASAN','TOTAL'],[[esc(drugs.find(d=>d.id===o.drug)?.name),o.qty,esc(o.unit),money(o.total)]]):'<div class="notice">Dokumen contoh untuk menunjukkan alur pemesanan dan penerimaan.</div>'}`,`${btn('Tutup','close-modal')}${o.status==='Draft'?btn('Kirim pesanan',`send-po:${id}`,'primary'):['Dipesan','Parsial'].includes(o.status)?btn('Terima barang',`receive:${id}`,'primary'):''}`)}
function receiveForm(id){const ordersOpen=orders.filter(o=>['Dipesan','Parsial'].includes(o.status));if(!ordersOpen.length){toast('Belum ada PO yang menunggu penerimaan.');return}const o=orders.find(o=>o.id===id)||ordersOpen[0];formModal('Penerimaan barang','Catat realisasi per batch. Penerimaan menambah stok dan kartu stok.','receive-form',`<div class="form-grid">${selectField('Referensi PO','po',ordersOpen.map(o=>o.id),o.id)}${field('Tanggal terima','date','2026-10-28','date',true)}${field('Nomor faktur supplier','invoice')}${selectField('Obat dari PO','drug',(o.drug?drugs.filter(d=>d.id===o.drug):drugs).map(d=>`${d.id} · ${d.name}`))}</div><h3 class="section-title">Batch penerimaan</h3><div id="batch-lines">${batchFields(1)}</div><div style="margin:16px 0">${btn('+ Tambah batch','add-batch','text')}</div>${textField('Catatan selisih (wajib jika penerimaan parsial)','note')}<label class="check-row" style="margin-top:16px"><input type="checkbox" name="partial"> Penerimaan parsial; PO masih menunggu sisa barang</label><div class="notice" style="margin-top:18px">Kuantitas dalam satuan dasar. Batch baru dicatat terpisah dengan tanggal kedaluwarsanya.</div>`,'Posting penerimaan',true)}
function batchFields(n){return `<div class="batch-line"><h4 style="font-size:11px;color:var(--muted)">Batch ${n}</h4><div class="form-grid">${field('Nomor batch','batch','', 'text',true)}${field('Tanggal kedaluwarsa','expiry','','date',true)}${field('Qty diterima (satuan dasar)','qty',1,'number',true)}${field('Harga beli aktual / satuan (Rp)','price',900,'number',true)}${field('Lokasi / rak','location','Rak A-01')}</div></div>`}
function opnameForm(){if(state.opname&&state.opname.status!=='Diposting'){opnameReview();return}formModal('Mulai stok opname','Ambil snapshot stok untuk penghitungan fisik.','opname-form',`<div class="form-grid">${field('Tanggal dan waktu','date','2026-10-28T11:00','datetime-local',true)}${selectField('Ruang lingkup','scope',['Semua obat','Obat Bebas','Obat Keras','Suplemen'])}${field('Petugas','user','Rofi Firdaus','text',true)}</div><div class="notice" style="margin-top:20px">Saldo saat mulai disimpan sebagai snapshot. Koreksi diposting setelah review dan persetujuan.</div>`,'Ambil snapshot & mulai')}
function opnameReview(){const o=state.opname;if(!o)return opnameForm();const locked=['Disetujui','Diposting'].includes(o.status);modal('Review stok opname',`${o.id} · ${o.scope} · ${o.status}`,`<form id="count-form"><div class="notice ${o.status==='Diposting'?'':'amber'}">${o.status==='Diposting'?'Koreksi stok telah diposting dan tercatat di kartu stok.':o.status==='Disetujui'?'Disetujui oleh Rofi Firdaus (Admin). Posting untuk menerapkan selisih.':'Isi stok fisik dan alasan setiap selisih. Persetujuan Admin diperlukan sebelum posting.'}</div>${table(['OBAT / BATCH','STOK SISTEM','STOK FISIK','SELISIH','ALASAN'],o.lines.map((l,i)=>[`${esc(l.name)}<small>${esc(l.batch)}</small>`,l.system,`<input style="width:85px" type="number" min="0" step="any" name="physical-${i}" data-count="${i}" value="${l.physical}" required ${locked?'readonly':''}>`,`<strong id="delta-${i}">${l.physical-l.system}</strong>`,`<input aria-label="Alasan selisih ${esc(l.name)}" name="reason-${i}" value="${esc(l.reason)}" placeholder="Wajib jika selisih" ${locked?'readonly':''}>`]))}</form>`,`${btn('Tutup','close-modal')}${o.status==='Diposting'?'':o.status==='Disetujui'?btn('Posting koreksi stok','post-opname','primary'):`<button class="btn primary" form="count-form">Simpan hitungan & setujui</button>`}`,true)}
function history(){modal('Riwayat transaksi','Penjualan final dan retur simulasi.',transactionTable(),btn('Tutup','close-modal'),true)}
function receipt(t){modal('Pratinjau struk',t.id,`<div class="receipt"><h3>${esc(state.settings.name)}</h3><p>${esc(state.settings.address)}<br>${esc(state.settings.phone)}<br>DATA DEMO — BUKAN BUKTI TRANSAKSI</p><hr><p>${t.id}<br>28/10/2026 ${t.time} WIB<br>Kasir: Rofi Firdaus</p>${table(['ITEM','QTY','TOTAL'],(t.lines||[{name:'Penjualan contoh',qty:t.items,price:t.total/t.items}]).map(l=>[esc(l.name),l.qty,money(l.price*l.qty)]))}<hr><div class="total-line"><strong>TOTAL</strong><strong>${money(t.total)}</strong></div><div class="total-line"><span>${esc(t.method)}</span><span>${money(t.paid||t.total)}</span></div><div class="total-line"><span>Kembalian</span><span>${money(Math.max(0,(t.paid||t.total)-t.total))}</span></div><hr><p>Terima kasih atas kunjungan Anda.<br>Semoga lekas sehat.</p></div>`,`${btn('Tutup','close-modal')}${btn('Cetak struk','print','primary','print')}`)}
function printRx(id){const r=prescriptions.find(r=>r.id===id),d=drugs.find(d=>d.id===r.drug);modal('Pratinjau resep',r.id,`<div class="receipt" style="max-width:550px"><h3>${esc(state.settings.name)}</h3><p>${esc(state.settings.address)}<br>${esc(state.settings.phone)}<br>CONTOH RESEP — DATA DEMO</p><hr><p style="text-align:left">${esc(r.doctor)}<br>Resep: ${r.id}<br>Tanggal: ${formatDate(r.date||'2026-10-28')}<br>Kunjungan: ${esc(r.visitId||'?')}<br>Pasien: ${esc(r.patient)}</p><hr><p style="text-align:left">R/ ${esc(d.name)} — ${r.qty} ${esc(d.unit)}<br>S: ${esc(r.dose)}, ${esc(r.frequency)}<br>${esc(r.instruction)}</p><hr>${r.signature?`<img src="${r.signature}" alt="Tanda tangan ${esc(r.doctor)}" style="display:block;margin-left:auto;max-width:160px;max-height:90px">`:'<p style="text-align:right;color:#a48052">Tanda tangan belum tersedia</p>'}<p style="text-align:right">${esc(r.doctor)}</p><p style="font-size:10px">Gambar tanda tangan; bukan tanda tangan digital tersertifikasi.</p></div>`,`${btn('Kembali',`rx:${id}`)}${btn('Cetak resep','print','primary','print')}`)}
function returnForm(){const t=transactions.find(t=>t.lines&&t.status==='Lunas');if(!t){modal('Retur penjualan','Pilih transaksi asal yang tercatat di sesi demo.','<div class="notice amber">Selesaikan satu penjualan di POS terlebih dahulu agar rincian obat dan batch tersedia untuk simulasi retur.</div>');return}formModal('Retur penjualan',`${t.id} · ${esc(t.customer)}`,'return-form',`<input name="trx" type="hidden" value="${t.id}"><div class="form-grid">${selectField('Item dari transaksi','item',t.lines.map(l=>`${l.id} · ${l.name}`))}${field('Qty retur','qty',1,'number',true)}${selectField('Kondisi barang','condition',['Layak stok','Rusak','Kedaluwarsa'])}${textField('Alasan retur','reason','',true)}</div><div class="notice amber" style="margin-top:18px">Persetujuan Admin diterapkan saat konfirmasi. Stok hanya dikembalikan untuk barang layak.</div>`,'Setujui & selesaikan retur')}
function exportCSV(){let headers,rows;if(page==='master'&&sub==='pemasok'){headers=['Kode','Nama','PIC','Telepon','Termin'];rows=suppliers.map(s=>[s.id,s.name,s.pic,s.phone,s.term])}else if(page==='laporan'||page==='kasir'||page==='dashboard'){headers=['Referensi','Waktu','Pelanggan','Total','Metode','Status'];rows=transactions.map(t=>[t.id,t.time,t.customer,t.total,t.method,t.status])}else{headers=['SKU','Nama obat','Kategori','Batch','Kedaluwarsa','Stok','Satuan','Harga jual'];rows=drugs.map(d=>[d.id,d.name,d.category,d.batch,d.expiry,d.stock,d.unit,d.price])}if(page==='master'&&['pasien','dokter'].includes(sub)){toast('Ekspor data klinis dibatasi pada prototipe ini.');return}const csv='\uFEFF'+[headers,...rows].map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`apotek-${page}-demo-20261028.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Laporan CSV berhasil diunduh.')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const [a,...args]=b.dataset.action.split(':');const id=args[0];switch(a){case'close-modal':closeModal();break;case'sub':sub=id;search='';filter='';pageIndex=1;location.hash=page+'/'+sub;render();break;case'stock-tab':stockTab=id;render();break;case'prev-page':pageIndex=Math.max(1,pageIndex-1);render();break;case'next-page':pageIndex=Math.min(Number(id),pageIndex+1);render();break;case'page':pageIndex=+id;render();break;case'export':exportCSV();break;case'new-drug':drugForm();break;case'drug':drugForm(id);break;case'new-supplier':personForm('supplier');break;case'supplier':personForm('supplier',id);break;case'new-patient':personForm('patient');break;case'edit-patient':personForm('patient',id);break;case'new-doctor':personForm('doctor');break;case'doctor':personForm('doctor',id);break;case'patient':patientDetail(id);break;case'new-visit':visitForm();break;case'examine':startExamination(id);break;case'amend':{const visit=findVisit(id);if(!visit||visit.exam?.status!=='Final')return toast('Catatan final tidak ditemukan.');formModal('Amendemen catatan final','Catatan asli tetap tersimpan.','amend-form',`<input type="hidden" name="visitId" value="${visit.id}"><div class="form-grid">${textField('Koreksi / tambahan catatan','text','',true)}${textField('Alasan amendemen','reason','',true)}</div>`,'Simpan amendemen');break;}case'new-rx':rxForm(id);break;case'rx':rxDetail(id);break;case'print-rx':printRx(id);break;case'prepare':{const r=prescriptions.find(r=>r.id===id),d=drugs.find(d=>d.id===r.drug);if(!available(d)||d.stock<r.qty)return toast('Stok tidak cukup atau batch tidak layak.');r.status='Disiapkan';audit('Verifikasi resep',id);rxDetail(id);render();toast('Resep diverifikasi dan siap diserahkan.');break}case'dispense':{const r=prescriptions.find(r=>r.id===id),d=drugs.find(d=>d.id===r.drug);if(r.status!=='Disiapkan'||!available(d)||d.stock<r.qty)return toast('Penyerahan gagal. Status atau stok telah berubah.');r.recipient=$('#recipient')?.value;r.status='Diserahkan';r.stockPosted=true;d.stock-=r.qty;ledger.unshift({ref:r.id,drug:d.name,type:'Penyerahan resep',in:0,out:r.qty,time:'28/10/2026 · sesi demo',user:'Rofi Firdaus'});audit('Penyerahan resep',id);closeModal(true);render();toast('Obat diserahkan. Mutasi stok tercatat satu kali.');break}case'pay-rx':{const r=prescriptions.find(r=>r.id===id);if(r.paid)return toast('Resep sudah dibayar.');selectedRx=id;posType='Resep';cart=[{id:r.drug,qty:r.qty}];closeModal(true);location.hash='kasir';if(page==='kasir')render();break}case'new-po':poForm();break;case'po':poDetail(id);break;case'send-po':orders.find(o=>o.id===id).status='Dipesan';audit('Kirim purchase order',id);poDetail(id);render();toast('PO dikirim ke alur penerimaan.');break;case'receive':receiveForm(id);break;case'add-batch':$('#batch-lines').insertAdjacentHTML('beforeend',batchFields($$('.batch-line').length+1));break;case'new-opname':opnameForm();break;case'review-opname':opnameReview();break;case'post-opname':postOpname();break;case'stock':{const d=drugs.find(d=>d.id===id);modal('Kartu stok',`${esc(d.name)} · ${d.batch}`,`<div class="notice">Saldo akhir: <strong>${d.stock} ${esc(d.unit)}</strong> · ED ${formatDate(d.expiry)}</div>${table(['WAKTU','REFERENSI','SUMBER','MASUK','KELUAR'],ledger.filter(l=>l.drug===d.name).map(l=>[l.time,l.ref,l.type,l.in,l.out]))}`,'',true);break}case'ledger':modal('Referensi mutasi',esc(id),table(['OBAT','SUMBER','MASUK','KELUAR','PETUGAS'],ledger.filter(l=>l.ref===id).map(l=>[esc(l.drug),l.type,l.in,l.out,esc(l.user)])));break;case'kasir':location.hash='kasir';break;case'add-cart':addCart(id);break;case'qty':{const c=cart.find(c=>c.id===id),d=drugs.find(d=>d.id===id);if(!c)break;if(c.qty+Number(args[1])>d.stock&&!prescriptions.find(r=>r.id===selectedRx)?.stockPosted)return toast('Jumlah melebihi stok tersedia.');c.qty+=Number(args[1]);cart=cart.filter(c=>c.qty>0);render();break}case'clear-cart':if(cart.length&&confirm('Kosongkan keranjang penjualan?')){cart=[];paid=0;render()}break;case'checkout':checkout();break;case'history':history();break;case'trx':receipt(transactions.find(t=>t.id===id));break;case'print':window.print();break;case'return':returnForm();break;case'retry':toast('Simulasi: data berhasil dimuat kembali.');break}});
const $$=s=>[...document.querySelectorAll(s)];
function addCart(id){const d=drugs.find(d=>d.id===id);if(!available(d))return toast('Batch tidak layak jual.');if(d.rx&&(posType!=='Resep'||!selectedRx))return toast('Obat ini memerlukan referensi resep dokter.');const r=prescriptions.find(r=>r.id===selectedRx);if(posType==='Resep'&&(!r||r.drug!==id))return toast('Obat harus sesuai referensi resep.');const c=cart.find(c=>c.id===id);if((c?.qty||0)+1>d.stock)return toast('Stok tidak mencukupi.');if(r&&(c?.qty||0)+1>r.qty)return toast('Jumlah tidak boleh melebihi resep.');if(c)c.qty++;else cart.push({id,qty:1});render()}
function checkout(){const total=subtotal();if(!cart.length)return;const r=prescriptions.find(r=>r.id===selectedRx);if(posType==='Resep'&&(!r||r.status!=='Diserahkan'||r.paid))return toast('Resep harus diserahkan farmasi dan belum dibayar.');if(posType==='Resep'&&(cart.length!==1||cart[0].id!==r.drug||cart[0].qty!==r.qty))return toast('Isi keranjang harus sesuai jumlah obat pada resep.');if(payment==='Tunai'&&paid<total){$('#paid-error').textContent='Nominal diterima harus sama atau lebih dari total.';$('#paid').setAttribute('aria-invalid','true');$('#paid').focus();return}if(!(posType==='Resep'&&r?.stockPosted)&&cart.some(c=>{const d=drugs.find(d=>d.id===c.id);return !available(d)||d.stock<c.qty}))return toast('Stok berubah atau batch tidak layak. Periksa keranjang.');const t={id:`TRX-20261028-${String(49+transactions.length-3).padStart(3,'0')}`,time:'11:00',customer:r&&posType==='Resep'?r.patient:'Pelanggan umum',items:cart.reduce((s,c)=>s+c.qty,0),total,method:payment,paid:payment==='Tunai'?paid:total,status:'Lunas',lines:cart.map(c=>{const d=drugs.find(d=>d.id===c.id);if(!(posType==='Resep'&&r?.stockPosted)){d.stock-=c.qty;ledger.unshift({ref:`TRX-20261028-${String(49+transactions.length-3).padStart(3,'0')}`,drug:d.name,type:'Penjualan',in:0,out:c.qty,time:'28/10/2026 · sesi demo',user:'Rofi Firdaus'})}return {id:d.id,name:d.name,qty:c.qty,price:d.price,batch:d.batch,returned:0}})};if(r&&posType==='Resep')r.paid=true;transactions.unshift(t);audit('Pembayaran final',t.id);cart=[];paid=0;selectedRx='';posType='Umum';render();receipt(t);toast('Pembayaran berhasil. Struk siap dicetak.')}
function postOpname(){const o=state.opname;if(!o||o.status!=='Disetujui')return;if(o.lines.some(l=>drugs.find(d=>d.id===l.id).stock!==l.system))return toast('Stok berubah setelah snapshot. Mulai ulang opname untuk mencegah koreksi salah.');if(!confirm('Posting koreksi stok? Mutasi final akan dicatat dan tidak bisa dihapus.'))return;o.lines.forEach(l=>{const d=drugs.find(d=>d.id===l.id),delta=l.physical-l.system;if(delta){d.stock=l.physical;ledger.unshift({ref:o.id,drug:d.name,type:'Koreksi opname',in:Math.max(0,delta),out:Math.max(0,-delta),time:'28/10/2026 · sesi demo',user:'Rofi Firdaus'})}});o.status='Diposting';audit('Posting koreksi opname',o.id);closeModal(true);render();toast('Koreksi stok diposting dan dicatat pada kartu stok.')}
document.addEventListener('input',e=>{if(e.target.closest('.modal'))modalDirty=true;if(['search','pos-search'].includes(e.target.id)){const cursor=e.target.selectionStart;search=e.target.value;pageIndex=1;render();const input=$('#'+e.target.id);input?.focus();input?.setSelectionRange(cursor,cursor)}if(e.target.id==='paid'){paid=+e.target.value;$('#change').textContent=money(Math.max(0,paid-subtotal()));$('#paid-error').textContent='';e.target.removeAttribute('aria-invalid')}if(e.target.dataset.count!==undefined){const i=+e.target.dataset.count;$('#delta-'+i).textContent=+e.target.value-state.opname.lines[i].system}if(e.target.closest('#po-form')){const f=$('#po-form'),v=new FormData(f);$('#po-total').textContent=money(Math.max(0,+v.get('qty')*+v.get('price')-+v.get('discount')+ +v.get('tax')))}});
document.addEventListener('change',e=>{switch(e.target.id){case'filter':case'pos-category':filter=e.target.value;pageIndex=1;render();break;case'period':period=e.target.value;render();break;case'payment':payment=e.target.value;render();break;case'pos-type':posType=e.target.value;cart=[];selectedRx='';paid=0;render();break;case'pos-rx':{selectedRx=e.target.value;const r=prescriptions.find(r=>r.id===selectedRx);cart=r?[{id:r.drug,qty:r.qty}]:[];render();break}}if(e.target.name==='patient'&&e.target.closest('#rx-form')){const p=patients.find(p=>p.id===e.target.value.split(' · ')[0]);$('#rx-allergy').textContent='Alergi pasien: '+(p?.allergy||'Tidak diketahui')+'. Verifikasi sebelum meresepkan.'}if(e.target.name==='po'&&e.target.closest('#receive-form')){const o=orders.find(o=>o.id===e.target.value);const select=$('#receive-form [name=drug]');select.innerHTML=(o.drug?drugs.filter(d=>d.id===o.drug):drugs).map(d=>`<option>${esc(d.id+' · '+d.name)}</option>`).join('')}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,v=Object.fromEntries(new FormData(f));try{switch(f.id){case'drug-form':{const old=drugs.find(d=>d.id===v.originalId);if(drugs.some(d=>d.id===v.id&&d!==old))throw Error('Kode obat sudah terdaftar. Gunakan SKU lain.');if(v.barcode&&drugs.some(d=>d.barcode===v.barcode&&d!==old))throw Error('Barcode sudah digunakan obat lain.');if(+v.conversion<=0)throw Error('Konversi satuan harus lebih dari 0.');if(v.max&&+v.max<+v.min)throw Error('Stok maksimum harus ≥ stok minimum.');if(old&&ledger.some(l=>l.drug===old.name)&&(+v.conversion!==old.conversion||v.unit!==old.unit))throw Error('Satuan dasar dan konversi obat yang sudah memiliki mutasi terkunci.');const d={...old,...v,conversion:+v.conversion,price:+v.price,buyPrice:+v.buyPrice,min:+v.min,max:+v.max,active:v.active==='on',rx:v.rx==='on',stock:old?.stock||0,batch:old?.batch||'Belum ada batch',expiry:old?.expiry||'2099-12-31'};if(old)drugs[drugs.indexOf(old)]=d;else drugs.push(d);audit('Simpan master obat',d.id);break}case'person-form':{const t=v.type,data=t==='patient'?patients:t==='doctor'?doctors:suppliers;const old=data.find(d=>d.id===v.originalId);if(v.nik&&!/^\d{16}$/.test(v.nik))throw Error('NIK harus tepat 16 digit.');if(v.birth>'2026-10-28')throw Error('Tanggal lahir tidak boleh di masa depan.');let signature=old?.signature;if(t==='doctor'){const file=f.signature.files[0];if(file?.size){if(file.size>2*1024*1024||!['image/png','image/jpeg'].includes(file.type))throw Error('Tanda tangan harus PNG/JPG maksimal 2 MB.');signature=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}}const d={...old,...v,id:old?.id||`${t==='patient'?'RM':t==='doctor'?'DOK':'SUP'}-${String(data.length+1).padStart(t==='patient'?4:3,'0')}`,active:true,signature,allergy:v.allergy||'Tidak diketahui',term:+v.term||0};if(old)data[data.indexOf(old)]=d;else data.push(d);audit('Simpan master '+t,d.id);if(t==='patient'&&v.returnToVisit==='1'){closeModal(true);render();visitForm(d.id);toast('Pasien tersimpan. Lengkapi pendaftaran kunjungan.');return}break}case'visit-form':{const visit=registerVisit(v);closeModal(true);page='layanan';sub='kunjungan';location.hash='layanan/kunjungan';startExamination(visit.id);toast('Pendaftaran berhasil. Lanjutkan pemeriksaan kunjungan ini.');return}case'exam-form':{const visit=saveExamination(v,true);closeModal(true);render();rxForm(visit.id);toast('Pemeriksaan final. Pasien dan dokter otomatis diteruskan ke resep.');return}case'amend-form':{const visit=visits.find(x=>x.id===v.visitId);if(!visit||visit.exam?.status!=='Final')throw Error('Catatan final tidak ditemukan.');visit.amendments.push({text:v.text,reason:v.reason,user:'Rofi Firdaus',time:'28/10/2026 ? sesi demo'});audit('Amendemen rekam medis',visit.id);break}case'rx-form':{const r=await finalizeClinicalPrescription(v,f);closeModal(true);render();clinicalHandoff(r);toast('Resep berhasil dikirim ke antrean farmasi.');return}case'po-form':{if(+v.qty<=0||+v.discount>+v.qty*+v.price)throw Error('Periksa jumlah item atau diskon yang melebihi subtotal.');if(v.eta&&v.eta<v.date)throw Error('Estimasi tiba harus ≥ tanggal PO.');orders.unshift({id:`PO/2026/10/${String(29+orders.length-3).padStart(3,'0')}`,supplier:v.supplier,date:formatDate(v.date),items:1,total:+v.qty*+v.price-+v.discount+ +v.tax,status:'Draft',drug:v.drug.split(' · ')[0],qty:+v.qty,unit:v.unit});audit('Buat purchase order',orders[0].id);break}case'receive-form':{const o=orders.find(o=>o.id===v.po),d=drugs.find(d=>d.id===v.drug.split(' · ')[0]);const lines=$$('.batch-line').map(el=>Object.fromEntries([...el.querySelectorAll('input')].map(i=>[i.name,i.value])));if(lines.some(l=>!l.batch.trim()||+l.qty<=0||l.expiry<=v.date))throw Error('Batch wajib diisi, qty > 0, dan kedaluwarsa harus sesudah tanggal terima.');if(new Set(lines.map(l=>l.batch.trim())).size!==lines.length)throw Error('Nomor batch tidak boleh duplikat dalam penerimaan ini.');if(v.partial==='on'&&!v.note.trim())throw Error('Catatan selisih wajib untuk penerimaan parsial.');const factor=o.unit==='Box'?d.conversion:1;const remaining=o.qty?o.qty*factor-(o.received||0):Infinity;const incoming=lines.reduce((s,l)=>s+ +l.qty,0);if(incoming>remaining)throw Error('Qty diterima melebihi sisa PO.');for(const l of lines){const target=drugs.find(x=>x.name===d.name&&x.batch===l.batch);if(target&&target.expiry!==l.expiry)throw Error('Tanggal kedaluwarsa tidak cocok dengan batch yang sudah ada.')}const ref=`PNR/2026/10/${String(22+ledger.filter(l=>l.type==='Penerimaan').length).padStart(3,'0')}`;for(const l of lines){const target=drugs.find(x=>x.name===d.name&&x.batch===l.batch);if(target)target.stock+=+l.qty;else if(d.stock===0&&d.batch==='Belum ada batch'){d.batch=l.batch;d.expiry=l.expiry;d.stock=+l.qty}else{drugs.push({...d,id:`${d.id}-B${drugs.length+1}`,batch:l.batch,expiry:l.expiry,stock:+l.qty,buyPrice:+l.price,location:l.location})}ledger.unshift({ref,drug:d.name,type:'Penerimaan',in:+l.qty,out:0,time:formatDate(v.date),user:'Rofi Firdaus'})}o.received=(o.received||0)+incoming;o.status=v.partial==='on'||o.qty&&o.received<o.qty*factor?'Parsial':'Diterima';audit('Posting penerimaan',ref);break}case'opname-form':{const lines=drugs.filter(d=>v.scope==='Semua obat'||d.category===v.scope).map(d=>({id:d.id,name:d.name,batch:d.batch,system:d.stock,physical:d.stock,reason:''}));state.opname={id:`OPN/2026/10/${audits.length}`,scope:v.scope,status:'Draft',lines};closeModal(true);opnameReview();return}case'count-form':{const o=state.opname;for(let i=0;i<o.lines.length;i++){const l=o.lines[i],physical=+v[`physical-${i}`],reason=v[`reason-${i}`];if(physical<0||!Number.isFinite(physical))throw Error('Stok fisik tidak boleh negatif.');if(physical!==l.system&&!reason.trim())throw Error('Alasan wajib untuk setiap selisih.')}if(!confirm('Setujui hasil penghitungan sebagai Admin?'))return;o.lines.forEach((l,i)=>{l.physical=+v[`physical-${i}`];l.reason=v[`reason-${i}`]});o.status='Disetujui';audit('Setujui opname',o.id);closeModal(true);opnameReview();render();return}case'return-form':{const t=transactions.find(t=>t.id===v.trx),l=t.lines.find(l=>l.id===v.item.split(' · ')[0]);if(+v.qty<=0||+v.qty>l.qty-l.returned)throw Error('Qty retur melebihi sisa item yang dapat diretur.');if(!confirm(`Setujui retur dan refund ${money(+v.qty*l.price)}?`))return;l.returned+=+v.qty;t.total-=+v.qty*l.price;if(!t.total)t.status='Diretur';const d=drugs.find(d=>d.id===l.id);if(v.condition==='Layak stok'){if(expired(d))throw Error('Batch telah kedaluwarsa; pilih kondisi kedaluwarsa.');d.stock+=+v.qty;ledger.unshift({ref:`RET-${t.id}`,drug:d.name,type:'Retur penjualan',in:+v.qty,out:0,time:'28/10/2026 · sesi demo',user:'Rofi Firdaus'})}audit('Retur penjualan',`${t.id} · ${v.reason}`);break}case'settings-form':state.settings={...state.settings,...v};audit('Ubah pengaturan','Profil / operasional');render();toast('Pengaturan disimpan untuk sesi demo.');return;case'report-filter':{const from=$('#report-from').value,to=$('#report-to').value,type=$('#report-type').value;if(from>to)throw Error('Tanggal awal harus sebelum atau sama dengan tanggal akhir.');const included=from<='2026-10-28'&&to>='2026-10-28';const rows=type==='Penjualan'?transactions.map(t=>[t.id,t.customer,money(t.total),t.status]):type==='Pembelian'?orders.map(o=>[o.id,o.supplier,money(o.total),o.status]):type==='Resep'?prescriptions.map(r=>[r.id,r.patient,r.doctor,r.status]):type==='Mutasi stok'?ledger.map(l=>[l.ref,l.drug,l.in,l.out]):drugs.filter(d=>type!=='Kedaluwarsa'||expired(d)||nearExpiry(d)).map(d=>[d.id,d.name,d.stock,formatDate(d.expiry)]);$('#report-content').innerHTML=`<div class="notice">${esc(type)} · ${formatDate(from)} – ${formatDate(to)} · Data simulasi hanya tersedia pada 28/10/2026.</div>${table(type==='Penjualan'?['REFERENSI','PELANGGAN','TOTAL','STATUS']:type==='Pembelian'?['REFERENSI','PEMASOK','TOTAL','STATUS']:type==='Resep'?['RESEP','PASIEN','DOKTER','STATUS']:type==='Mutasi stok'?['REFERENSI','OBAT','MASUK','KELUAR']:['SKU','OBAT','STOK','KEDALUWARSA'],included?rows.map(r=>r.map(esc)):[])}`;return}default:return}closeModal(true);render();toast('Data berhasil disimpan pada sesi demo.')}catch(err){toast(err.message)}});
