$('#notifications').onclick=()=>modal('Notifikasi persediaan','Prioritaskan obat yang membutuhkan tindak lanjut.',`<div class="notice red">${drugs.filter(expired).length} batch kedaluwarsa diblokir dari penjualan.</div><div class="notice amber">${drugs.filter(nearExpiry).length} batch mendekati kedaluwarsa.</div><div class="notice amber">${drugs.filter(d=>d.stock<d.min&&!expired(d)).length} obat di bawah stok minimum.</div>`,`${btn('Tutup','close-modal')}<a class="btn primary" href="#persediaan" data-action="close-modal">Lihat persediaan</a>`);
$('#profile').onclick=()=>modal('Profil pengguna','Akun demonstrasi',`<dl class="detail-grid"><div><dt>Nama</dt><dd>Rofi Firdaus</dd></div><div><dt>Peran</dt><dd>Administrator</dd></div><div><dt>Outlet</dt><dd>Sehat Jiwa Farma Utama</dd></div></dl><div class="notice">Semua data adalah simulasi dan akan kembali ke awal saat halaman dimuat ulang.</div>`);
$('#guide').onclick=()=>modal('Panduan prototipe','Jelajahi enam alur operasional utama.',`<div class="timeline"><div><strong>Pembelian → penerimaan</strong><p>Buat PO, kirim pesanan, lalu terima barang per batch.</p></div><div><strong>Persediaan → stok opname</strong><p>Ambil snapshot, isi stok fisik dan alasan, setujui, lalu posting.</p></div><div><strong>Pasien → pemeriksaan → resep</strong><p>Daftar pasien, finalkan SOAP, unggah tanda tangan dokter dan buat resep.</p></div><div><strong>Farmasi → kasir</strong><p>Verifikasi resep, serahkan obat, lalu catat pembayaran tanpa pemotongan stok kedua.</p></div><div><strong>Penjualan umum → retur</strong><p>Tambahkan obat ke keranjang, isi nominal bayar, cetak struk dan coba retur.</p></div><div><strong>Laporan & state UI</strong><p>Ekspor CSV dan lihat contoh loading, empty, error serta akses terbatas di Pengaturan.</p></div></div>`);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.modal')){e.preventDefault();closeModal()}if(e.key==='Tab'&&$('.modal')){const nodes=$$('.modal button:not([disabled]),.modal input:not([hidden]),.modal select,.modal textarea,.modal a').filter(el=>el.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}if(page==='kasir'&&!$('.modal')){if(e.key==='F2'){e.preventDefault();$('#pos-search').focus()}if(e.key==='F8'){e.preventDefault();checkout()}}});
window.addEventListener('beforeunload',e=>{if(cart.length||modalDirty){e.preventDefault();e.returnValue=''}});
window.addEventListener('hashchange',navigate);navigate();
